mapper.select:
SELECT * FROM ACTUAL_CONTROLLER
WHERE CONTROL_STATUS = #{controlStatus}
ORDER BY UPDATE_TIME DESC

SELECT * FROM ACTUAL_CONTROLLER
WHERE CONFIRMATION_STATUS = #{confirmationStatus}
ORDER BY UPDATE_TIME DESC

mapper.delete:
DELETE FROM ACTUAL_CONTROLLER WHERE CONTROL_STATUS = 'TERMINATED' AND UPDATE_TIME <
DATE_SUB(NOW(), INTERVAL #{days} DAY)
SYSDATE - #{days}
